-- FRUITNINJA2
-- Do not edit this file. Any change breaks the decoder.
local _pykssh = 223
local _ajmimg = 219
local _udgmem = 120
local _psmaoy = ""

local _prkfyx = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _sxpjkr(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _mtusew(d)
	d = d:gsub("[^" .. _prkfyx .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_prkfyx:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _onhoyw = _mtusew(_psmaoy)
local _etickl = { _pykssh, _ajmimg, _udgmem }
local _zhcvgh = {}
for i = 1, #_onhoyw do
	_zhcvgh[i] = string.char(_sxpjkr(_onhoyw:byte(i), _etickl[(i - 1) % 3 + 1]))
end

local _mzzlil = load or loadstring
local _tizzbj, _ljfrrw = _mzzlil(table.concat(_zhcvgh), "=w")
if not _tizzbj then
	gg.alert("Corrupted file: " .. tostring(_ljfrrw))
	os.exit()
end
_tizzbj()
